# Check for anomalous weight norms in MLP (possible signature of the earlier edit)
for L in [21,22,23]:
    for wname in ['gate_proj','up_proj','down_proj']:
        W = get_tensor(f'model.language_model.layers.{L}.mlp.{wname}.weight').numpy()
        if wname=='down_proj':
            colnorm = np.linalg.norm(W, axis=0)  # per unit
            order = np.argsort(-colnorm)
            print(f'L{L} {wname} col-norms top5:', [(int(i), round(float(colnorm[i]),2)) for i in order[:5]], 'median', round(float(np.median(colnorm)),2))
        else:
            rownorm = np.linalg.norm(W, axis=1)
            order = np.argsort(-rownorm)
            print(f'L{L} {wname} row-norms top5:', [(int(i), round(float(rownorm[i]),2)) for i in order[:5]], 'median', round(float(np.median(rownorm)),2))
